package lk.prime.dailyactivity

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

private const val PRIME_LOGO_1 = ""
private const val PRIME_LOGO_2 = ""
private const val PRIME_LOGO_3 = ""
private const val PRIME_LOGO_4 = ""

@Composable
fun PrimeOfficialLogo(
    modifier: Modifier = Modifier,
    contentScale: ContentScale = ContentScale.Fit
) {
    val logo = remember {
        runCatching {
            val encoded = PRIME_LOGO_1 + PRIME_LOGO_2 + PRIME_LOGO_3 + PRIME_LOGO_4
            val bytes = Base64.decode(encoded, Base64.DEFAULT)
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
        }.getOrNull()
    }
    logo?.let {
        Image(
            bitmap = it,
            contentDescription = "PRIME Agri Business & Plantations",
            modifier = modifier,
            contentScale = contentScale
        )
    }
}
